//
//  SwiftForgeTheme+Mono.swift
//  SwiftForgeUI
//
//  Colors are generated by scripts/theme-design (see docs/design/themes/mono.md)
//  and verified by SwiftForgeContrastAudit in every test run.
//

import SwiftUI

extension SwiftForgeTheme {

    /// A terminal: SF Mono everywhere, one phosphor-green accent, hairline
    /// boxes with almost square corners, no shadows, and a dense layout.
    ///
    /// Spacing is three quarters of ``forge``'s and controls are visually
    /// shorter (28, 36, and 44 pt), while every hit area stays 44 pt. Motion
    /// is quick and never bounces. Status colors keep their meaning — amber
    /// warnings, red errors — in terminal hues.
    public static let mono: SwiftForgeTheme = {
        typealias P = Palette.Mono
        let accent = SwiftForgeToneColors(
            solid: SwiftForgeColor(
                light: P.Phosphor.s700, dark: P.glow, lightHighContrast: P.Phosphor.s800, darkHighContrast: P.Phosphor.s200),
            onSolid: SwiftForgeColor(light: Palette.white, dark: P.term, darkHighContrast: Palette.black),
            text: SwiftForgeColor(
                light: P.Phosphor.s700, dark: P.glow, lightHighContrast: P.Phosphor.s800, darkHighContrast: P.Phosphor.s200),
            subtle: SwiftForgeColor(
                light: P.Phosphor.s50, dark: P.Phosphor.s950, lightHighContrast: P.Phosphor.s100,
                darkHighContrast: P.Phosphor.s900)
        )
        let colors = SwiftForgeColors(
            canvas: SwiftForgeColor(light: P.paper, dark: P.term),
            surface: SwiftForgeColor(light: Palette.white, dark: P.termPanel),
            surfaceRaised: SwiftForgeColor(light: Palette.white, dark: P.termLift),
            fillMuted: SwiftForgeColor(
                light: P.Moss.s100, dark: P.Moss.s900, lightHighContrast: P.Moss.s200, darkHighContrast: P.Moss.s800),
            textPrimary: SwiftForgeColor(
                light: P.ink, dark: P.phosphorText, lightHighContrast: Palette.black, darkHighContrast: Palette.white),
            textSecondary: SwiftForgeColor(
                light: P.Moss.s700, dark: P.Moss.s300, lightHighContrast: P.Moss.s800, darkHighContrast: P.Moss.s200),
            borderSubtle: SwiftForgeColor(
                light: P.Moss.s200, dark: P.Moss.s800, lightHighContrast: P.Moss.s400, darkHighContrast: P.Moss.s600),
            borderStrong: SwiftForgeColor(
                light: P.Moss.s500, dark: P.Moss.s500, lightHighContrast: P.Moss.s700, darkHighContrast: P.Moss.s300),
            focusRing: accent.text,
            pressedOverlay: SharedTokens.pressedOverlay,
            accent: accent,
            neutral: SwiftForgeToneColors(
                solid: SwiftForgeColor(
                    light: P.Moss.s800, dark: P.Moss.s300, lightHighContrast: P.Moss.s900, darkHighContrast: P.Moss.s200),
                onSolid: SwiftForgeColor(light: Palette.white, dark: P.term, darkHighContrast: Palette.black),
                text: SwiftForgeColor(
                    light: P.Moss.s700, dark: P.Moss.s300, lightHighContrast: P.Moss.s800, darkHighContrast: P.Moss.s200),
                subtle: SwiftForgeColor(
                    light: P.Moss.s100, dark: P.Moss.s900, lightHighContrast: P.Moss.s200, darkHighContrast: P.Moss.s800)
            ),
            info: SwiftForgeToneColors(
                solid: SwiftForgeColor(
                    light: P.Cyan.s700, dark: P.cyan, lightHighContrast: P.Cyan.s800, darkHighContrast: P.Cyan.s200),
                onSolid: SwiftForgeColor(light: Palette.white, dark: P.term, darkHighContrast: Palette.black),
                text: SwiftForgeColor(
                    light: P.Cyan.s700, dark: P.cyan, lightHighContrast: P.Cyan.s800, darkHighContrast: P.Cyan.s200),
                subtle: SwiftForgeColor(
                    light: P.Cyan.s50, dark: P.Cyan.s950, lightHighContrast: P.Cyan.s100, darkHighContrast: P.Cyan.s900)
            ),
            success: SwiftForgeToneColors(
                solid: SwiftForgeColor(
                    light: P.Phosphor.s700, dark: P.glow, lightHighContrast: P.Phosphor.s800, darkHighContrast: P.Phosphor.s200),
                onSolid: SwiftForgeColor(light: Palette.white, dark: P.term, darkHighContrast: Palette.black),
                text: SwiftForgeColor(
                    light: P.Phosphor.s700, dark: P.glow, lightHighContrast: P.Phosphor.s800, darkHighContrast: P.Phosphor.s200),
                subtle: SwiftForgeColor(
                    light: P.Phosphor.s50, dark: P.Phosphor.s950, lightHighContrast: P.Phosphor.s100,
                    darkHighContrast: P.Phosphor.s900)
            ),
            warning: SwiftForgeToneColors(
                solid: SwiftForgeColor(
                    light: P.amber, dark: P.amber, lightHighContrast: P.Amber.s300, darkHighContrast: P.Amber.s200),
                onSolid: SwiftForgeColor(light: Palette.black, dark: P.term, darkHighContrast: Palette.black),
                text: SwiftForgeColor(
                    light: P.Amber.s700, dark: P.amber, lightHighContrast: P.Amber.s800, darkHighContrast: P.Amber.s200),
                subtle: SwiftForgeColor(
                    light: P.Amber.s50, dark: P.Amber.s950, lightHighContrast: P.Amber.s100, darkHighContrast: P.Amber.s900)
            ),
            danger: SwiftForgeToneColors(
                solid: SwiftForgeColor(
                    light: P.Red.s700, dark: P.red, lightHighContrast: P.Red.s800, darkHighContrast: P.Red.s200),
                onSolid: SwiftForgeColor(light: Palette.white, dark: P.term, darkHighContrast: Palette.black),
                text: SwiftForgeColor(
                    light: P.Red.s700, dark: P.red, lightHighContrast: P.Red.s800, darkHighContrast: P.Red.s200),
                subtle: SwiftForgeColor(
                    light: P.Red.s50, dark: P.Red.s950, lightHighContrast: P.Red.s100, darkHighContrast: P.Red.s900)
            )
        )
        return SwiftForgeTheme(
            id: "mono",
            displayName: "Mono",
            colors: colors,
            typography: SwiftForgeTypography.standard
                .updating(SwiftForgeTypography.allRoles) { $0.design = .monospaced }
                .updating([\.controlLabel, \.controlLabelSmall]) { $0.weight = .medium },
            spacing: SwiftForgeSpacing(
                xxxs: 2, xxs: 3, xs: 6, sm: 9, md: 12, lg: 15, xl: 18, xxl: 24, xxxl: 30,
                screenHorizontal: 12, section: 18, component: 9, cardPadding: 12
            ),
            radius: SwiftForgeRadius(
                xs: 0, sm: 1, md: 2, lg: 2, xl: 3, xxl: 4,
                control: 2, controlSmall: 1, card: 2, sheet: 4,
                cornerStyle: .circular
            ),
            sizes: SwiftForgeSizes(
                minimumHitTarget: 44, controlHeightSmall: 28, controlHeightRegular: 36, controlHeightLarge: 44,
                iconSmall: 14, iconRegular: 16, iconLarge: 20
            ),
            elevation: SharedTokens.flat,
            motion: SwiftForgeMotion(
                fast: SwiftForgeMotionToken(duration: 0.1),
                standard: SwiftForgeMotionToken(duration: 0.16),
                emphasized: SwiftForgeMotionToken(duration: 0.22),
                shimmerDuration: 1.0,
                pressedScale: 1
            ),
            components: SwiftForgeComponentTokens(
                button: SwiftForgeButtonTokens(pressEffect: .scale(1)),
                card: SwiftForgeCardTokens(pressEffect: .scale(1)),
                surface: SwiftForgeSurfaceTokens(bordersEverySurface: true),
                toggle: SwiftForgeToggleTokens(trackWidth: 40, trackHeight: 22, thumbInset: 3, cornerRadius: 2),
                badge: SwiftForgeBadgeTokens(
                    cornerRadius: 2, countDiameter: 16, countDiameterSmall: 14, countDiameterLarge: 20, dotDiameter: 6),
                progress: SwiftForgeProgressTokens(
                    barHeight: 3, barHeightLarge: 6, barCornerRadius: 0,
                    ringDiameters: SwiftForgeControlSizeValues(small: 20, regular: 28, large: 44),
                    ringLineWidth: 3, ringLineWidthLarge: 4),
                selectionControl: SwiftForgeSelectionControlTokens(size: 18, borderWidth: 1),
                segmentedControl: SwiftForgeSegmentedControlTokens(indicatorElevation: .none, borderWidth: 1),
                slider: SwiftForgeSliderTokens(trackHeight: 2, thumbDiameter: 16, thumbCornerRadius: 1, thumbElevation: .none),
                avatar: SwiftForgeAvatarTokens(
                    diameters: SwiftForgeControlSizeValues(small: 24, regular: 32, large: 48), cornerRadius: 2),
                emptyState: SwiftForgeEmptyStateTokens(iconSize: 36),
                tabBar: SwiftForgeTabBarTokens(height: 44, iconSize: 20)
            )
        )
    }()
}
